INSERT INTO gratitude_quotes (day_of_year, quote, author) VALUES
-- January (Days 1-31)
(1, 'Gratitude is not only the greatest of virtues but the parent of all the others.', 'Cicero'),
(2, 'Gratitude turns what we have into enough.', 'Melody Beattie'),
(3, 'The root of joy is gratefulness.', 'David Steindl-Rast'),
(4, 'When you are grateful, fear disappears and abundance appears.', 'Tony Robbins'),
(5, 'Gratitude is the sign of noble souls.', 'Aesop'),
(6, 'Acknowledging the good that you already have in your life is the foundation for all abundance.', 'Eckhart Tolle'),
(7, 'Gratitude makes sense of your past, brings peace for today, and creates a vision for tomorrow.', 'Melody Beattie'),
(8, 'Let us be grateful to the people who make us happy; they are the charming gardeners who make our souls blossom.', 'Marcel Proust'),
(9, 'As we express our gratitude, we must never forget that the highest appreciation is not to utter words, but to live by them.', 'John F. Kennedy'),
(10, 'Gratitude is the wine for the soul. Go on. Get drunk.', 'Rumi'),
(11, 'He is a wise man who does not grieve for the things which he has not, but rejoices for those which he has.', 'Epictetus'),
(12, 'The real gift of gratitude is that the more grateful you are, the more present you become.', 'Robert Holden'),
(13, 'Enjoy the little things, for one day you may look back and realize they were the big things.', 'Robert Brault'),
(14, 'In ordinary life, we hardly realize that we receive a great deal more than we give, and that it is only with gratitude that life becomes rich.', 'Dietrich Bonhoeffer'),
(15, 'Gratitude is a powerful catalyst for happiness. It is the spark that lights a fire of joy in your soul.', 'Amy Collette'),
(16, 'The struggle ends when the gratitude begins.', 'Neale Donald Walsch'),
(17, 'Gratitude is the fairest blossom which springs from the soul.', 'Henry Ward Beecher'),
(18, 'When I started counting my blessings, my whole life turned around.', 'Willie Nelson'),
(19, 'Feeling gratitude and not expressing it is like wrapping a present and not giving it.', 'William Arthur Ward'),
(20, 'Piglet noticed that even though he had a very small heart, it could hold a rather large amount of gratitude.', 'A.A. Milne'),
(21, 'There is always, always, always something to be thankful for.', 'Unknown'),
(22, 'The thankful heart opens our eyes to a multitude of blessings that continually surround us.', 'James E. Faust'),
(23, 'Gratitude and attitude are not challenges; they are choices.', 'Robert Braathe'),
(24, 'Be thankful for what you have; you will end up having more.', 'Oprah Winfrey'),
(25, 'No one who achieves success does so without the help of others. The wise and confident acknowledge this help with gratitude.', 'Alfred North Whitehead'),
(26, 'We can only be said to be alive in those moments when our hearts are conscious of our treasures.', 'Thornton Wilder'),
(27, 'Gratitude is an antidote to negative emotions, a neutralizer of envy, hostility, worry, and irritation.', 'Robert Emmons'),
(28, 'The essence of all beautiful art, all great art, is gratitude.', 'Friedrich Nietzsche'),
(29, 'If you want to find happiness, find gratitude.', 'Steve Maraboli'),
(30, 'Gratitude is one of the most medicinal emotions we can feel. It elevates, energizes, inspires, and transforms.', 'Doc Childre'),
(31, 'Silent gratitude is not much use to anyone.', 'Gertrude Stein'),

-- February (Days 32-59)
(32, 'Let us rise up and be thankful, for if we didn''t learn a lot today, at least we learned a little.', 'Buddha'),
(33, 'Develop an attitude of gratitude, and give thanks for everything that happens to you.', 'Brian Tracy'),
(34, 'Gratitude is the memory of the heart.', 'Jean-Baptiste Massieu'),
(35, 'I would maintain that thanks are the highest form of thought; and that gratitude is happiness doubled by wonder.', 'G.K. Chesterton'),
(36, 'The more grateful I am, the more beauty I see.', 'Mary Davis'),
(37, 'Wear gratitude like a cloak, and it will feed every corner of your life.', 'Rumi'),
(38, 'What separates privilege from entitlement is gratitude.', 'Brené Brown'),
(39, 'Gratitude bestows reverence, allowing us to encounter everyday epiphanies.', 'John Milton'),
(40, 'When eating fruit, remember the one who planted the tree.', 'Vietnamese Proverb'),
(41, 'Joy is the simplest form of gratitude.', 'Karl Barth'),
(42, 'A grateful heart is a magnet for miracles.', 'Unknown'),
(43, 'It is not happiness that brings us gratitude. It is gratitude that brings us happiness.', 'Unknown'),
(44, 'The way to develop the best that is in a person is by appreciation and encouragement.', 'Charles Schwab'),
(45, 'At times, our own light goes out and is rekindled by a spark from another person. Each of us has cause to think with deep gratitude of those who have lighted the flame within us.', 'Albert Schweitzer'),
(46, 'If the only prayer you ever say in your entire life is thank you, it will be enough.', 'Meister Eckhart'),
(47, 'Thank you is the best prayer that anyone could say. Thank you expresses extreme gratitude, humility, understanding.', 'Alice Walker'),
(48, 'Gratitude is the healthiest of all human emotions. The more you express gratitude for what you have, the more likely you will have even more to express gratitude for.', 'Zig Ziglar'),
(49, 'Two kinds of gratitude: the sudden kind we feel for what we take, the larger kind we feel for what we give.', 'Edwin Arlington Robinson'),
(50, 'I don''t have to chase extraordinary moments to find happiness — it''s right in front of me if I''m paying attention and practicing gratitude.', 'Brené Brown'),
(51, 'When we focus on our gratitude, the tide of disappointment goes out and the tide of love rushes in.', 'Kristin Armstrong'),
(52, 'Gratitude opens the door to the power, the wisdom, the creativity of the universe.', 'Deepak Chopra'),
(53, 'Give thanks for a little and you will find a lot.', 'Hausa Proverb'),
(54, 'Enough is a feast.', 'Buddhist Proverb'),
(55, 'Trade your expectation for appreciation and the world changes instantly.', 'Tony Robbins'),
(56, 'Thankfulness is the beginning of gratitude. Gratitude is the completion of thankfulness.', 'Henri Frederic Amiel'),
(57, 'We often take for granted the very things that most deserve our gratitude.', 'Cynthia Ozick'),
(58, 'The unthankful heart discovers no mercies; but the thankful heart will find, in every hour, some heavenly blessings.', 'Henry Ward Beecher'),
(59, 'It''s a funny thing about life, once you begin to take note of the things you are grateful for, you begin to lose sight of the things that you lack.', 'Germany Kent'),

-- March (Days 60-90)
(60, 'There are only two ways to live your life. One is as though nothing is a miracle. The other is as though everything is a miracle.', 'Albert Einstein'),
(61, 'Start each day with a positive thought and a grateful heart.', 'Roy T. Bennett'),
(62, 'Some people grumble that roses have thorns; I am grateful that thorns have roses.', 'Alphonse Karr'),
(63, 'Gratitude helps you to grow and expand; gratitude brings joy and laughter into your life and into the lives of all those around you.', 'Eileen Caddy'),
(64, 'The soul that gives thanks can find comfort in everything; the soul that complains can find comfort in nothing.', 'Hannah Whitall Smith'),
(65, 'When we give cheerfully and accept gratefully, everyone is blessed.', 'Maya Angelou'),
(66, 'Do not spoil what you have by desiring what you have not; remember that what you now have was once among the things you only hoped for.', 'Epicurus'),
(67, 'True forgiveness is when you can say, Thank you for that experience.', 'Oprah Winfrey'),
(68, 'God gave you a gift of 86,400 seconds today. Have you used one to say thank you?', 'William Arthur Ward'),
(69, 'You cannot do a kindness too soon because you never know how soon it will be too late.', 'Ralph Waldo Emerson'),
(70, 'Reflect upon your present blessings, of which every man has plenty; not on your past misfortunes, of which all men have some.', 'Charles Dickens'),
(71, 'Appreciation is a wonderful thing. It makes what is excellent in others belong to us as well.', 'Voltaire'),
(72, 'I am happy because I''m grateful. I choose to be grateful. That gratitude allows me to be happy.', 'Will Arnett'),
(73, 'We should certainly count our blessings, but we should also make our blessings count.', 'Neal A. Maxwell'),
(74, 'The deepest craving of human nature is the need to be appreciated.', 'William James'),
(75, 'Cultivate the habit of being grateful for every good thing that comes to you, and to give thanks continuously.', 'Ralph Waldo Emerson'),
(76, 'Gratefulness is the key to a happy life that we hold in our hands, because if we are not grateful, then no matter how much we have we will not be happy.', 'David Steindl-Rast'),
(77, 'In all things give thanks.', '1 Thessalonians 5:18'),
(78, 'The greatest blessings of mankind are within us and within our reach. A wise man is content with his lot, whatever it may be, without wishing for what he has not.', 'Seneca'),
(79, 'To speak gratitude is courteous and pleasant, to enact gratitude is generous and noble, but to live gratitude is to touch Heaven.', 'Johannes A. Gaertner'),
(80, 'One can never pay in gratitude; one can only pay in kind somewhere else in life.', 'Anne Morrow Lindbergh'),
(81, 'Happiness cannot be traveled to, owned, earned, worn or consumed. Happiness is the spiritual experience of living every minute with love, grace, and gratitude.', 'Denis Waitley'),
(82, 'I awoke this morning with devout thanksgiving for my friends, the old and the new.', 'Ralph Waldo Emerson'),
(83, 'This is a wonderful day. I''ve never seen this one before.', 'Maya Angelou'),
(84, 'The miracle is not to walk on water. The miracle is to walk on the green earth, dwelling deeply in the present moment and feeling truly alive.', 'Thich Nhat Hanh'),
(85, 'Let gratitude be the pillow upon which you kneel to say your nightly prayer.', 'Maya Angelou'),
(86, 'Every day, think as you wake up, today I am fortunate to be alive, I have a precious human life, I am not going to waste it.', 'Dalai Lama'),
(87, 'Appreciation can change a day, even change a life. Your willingness to put it into words is all that is necessary.', 'Margaret Cousins'),
(88, 'It is impossible to feel grateful and depressed in the same moment.', 'Naomi Williams'),
(89, 'Think of all the beauty still left around you and be happy.', 'Anne Frank'),
(90, 'Saying thank you is more than good manners. It is good spirituality.', 'Alfred Painter'),

-- April (Days 91-120)
(91, 'Look at everything always as though you were seeing it either for the first or last time.', 'Betty Smith'),
(92, 'Thankfulness creates gratitude which generates contentment that causes peace.', 'Todd Stocker'),
(93, 'There is a calmness to a life lived in gratitude, a quiet joy.', 'Ralph H. Blum'),
(94, 'Nothing is more honorable than a grateful heart.', 'Seneca'),
(95, 'The world has enough beautiful mountains and meadows. What the world needs more of is people to appreciate and enjoy it.', 'Michael Josephson'),
(96, 'Feeling grateful or appreciative of someone or something in your life actually attracts more of the things that you appreciate and value into your life.', 'Christiane Northrup'),
(97, 'When you practice gratefulness, there is a sense of respect toward others.', 'Dalai Lama'),
(98, 'Whatever we are waiting for — peace of mind, contentment, grace — it will surely come to us, but only when we are ready to receive it with an open and grateful heart.', 'Sarah Ban Breathnach'),
(99, 'There is no such thing as gratitude unexpressed. If it is unexpressed, it is plain, old-fashioned ingratitude.', 'Robert Brault'),
(100, 'Every blessing ignored becomes a curse.', 'Paulo Coelho'),
(101, 'Not what we say about our blessings, but how we use them, is the true measure of our thanksgiving.', 'W.T. Purkiser'),
(102, 'We must find time to stop and thank the people who make a difference in our lives.', 'John F. Kennedy'),
(103, 'What if you gave someone a gift, and they neglected to thank you for it — would you be likely to give them another? Life is the same way. In order to attract more of the blessings that life has to offer, you must truly appreciate what you already have.', 'Ralph Marston'),
(104, 'Gratitude is when memory is stored in the heart and not in the mind.', 'Lionel Hampton'),
